import type { ComponentProps, JSX } from "react";

import { cn } from "@/lib/utils";

// Every icon in Nenu draws through this file, so the set is changed here and nowhere else. Glyphs are
// vendored as path data (no icon package at runtime): Hugeicons Stroke Rounded from
// @hugeicons/core-free-icons 4.3.5 (MIT), stroked on a 24 grid at 1.5 by default, and Phosphor Regular
// from @phosphor-icons/core 2.1.1 (MIT) for the agent and its messages, filled on a 256 grid whose
// 16-unit outline matches that 1.5. Each glyph's element paths are joined into one path in relative
// commands, circles are written as two arcs, and coordinates are rounded to 0.01 (under 0.004 px at
// 16 px). Licenses: THIRD_PARTY_NOTICES.md.

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { size?: number | string };
export type IconComponent = (props: IconProps) => JSX.Element;

/** One glyph as an svg: decorative unless it is given an accessible name. */
export function Icon({ name, d, filled = false, size = 24, strokeWidth = 1.5, className, ...props }: IconProps & { name: string; d: string; filled?: boolean }) {
  const named = props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox={filled ? "0 0 256 256" : "0 0 24 24"}
      fill={filled ? "currentColor" : "none"} {...(filled ? {} : { stroke: "currentColor", strokeWidth, strokeLinecap: "round", strokeLinejoin: "round" } as const)}
      aria-hidden={named ? undefined : true} className={cn("icon", `icon-${name}`, className)} {...props}>
      <path d={d} />
    </svg>
  );
}

const stroke = (name: string, d: string): IconComponent => (props) => <Icon name={name} d={d} {...props} />;
const fill = (name: string, d: string): IconComponent => (props) => <Icon name={name} d={d} filled {...props} />;

